static uint8_t custom_is_leap_year(uint16_t year)
{
    if ((year % 400U) == 0U)
    {
        return 1U;
    }
    if ((year % 100U) == 0U)
    {
        return 0U;
    }
    return ((year % 4U) == 0U) ? 1U : 0U;
}

static uint8_t custom_days_in_month(uint16_t year, uint8_t month)
{
    static const uint8_t s_days[12] = {31U, 28U, 31U, 30U, 31U, 30U, 31U, 31U, 30U, 31U, 30U, 31U};
    uint8_t days;

    if (month < 1U || month > 12U)
    {
        return 0U;
    }
    days = s_days[month - 1U];
    if (month == 2U && custom_is_leap_year(year))
    {
        days = 29U;
    }
    return days;
}

static uint8_t custom_datetime_is_valid(uint16_t year, uint8_t month, uint8_t day,
                                        uint8_t hour, uint8_t minute, uint8_t second)
{
    uint8_t month_days = custom_days_in_month(year, month);

    if (year < 1970U || year > 2099U)
    {
        return 0U;
    }
    if (month_days == 0U || day < 1U || day > month_days)
    {
        return 0U;
    }
    if (hour > 23U || minute > 59U || second > 59U)
    {
        return 0U;
    }
    return 1U;
}

static void custom_datetime_tick_one_second(void)
{
    uint8_t month_days;

    s_datetime.second++;
    if (s_datetime.second < 60U)
    {
        return;
    }
    s_datetime.second = 0U;
    s_datetime.minute++;
    if (s_datetime.minute < 60U)
    {
        return;
    }
    s_datetime.minute = 0U;
    s_datetime.hour++;
    if (s_datetime.hour < 24U)
    {
        return;
    }
    s_datetime.hour = 0U;
    s_datetime.day++;
    month_days = custom_days_in_month(s_datetime.year, s_datetime.month);
    if (month_days != 0U && s_datetime.day <= month_days)
    {
        return;
    }
    s_datetime.day = 1U;
    s_datetime.month++;
    if (s_datetime.month <= 12U)
    {
        return;
    }
    s_datetime.month = 1U;
    s_datetime.year++;
}

static void custom_datetime_set(uint16_t year, uint8_t month, uint8_t day,
                                uint8_t hour, uint8_t minute, uint8_t second)
{
    if (!custom_datetime_is_valid(year, month, day, hour, minute, second))
    {
        CUSTOM_UI_LOG("datetime ignore invalid %u-%u-%u %u:%u:%u",
                      year, month, day, hour, minute, second);
        return;
    }

    s_datetime.year = year;
    s_datetime.month = month;
    s_datetime.day = day;
    s_datetime.hour = hour;
    s_datetime.minute = minute;
    s_datetime.second = second;
    s_datetime_valid = 1U;
    s_datetime_anchor_ms = lv_tick_get();
    s_last_datetime_ui_sec = 60U;
    s_datetime_dirty = 1U;
}

static void custom_datetime_update_running(void)
{
    uint32_t now_ms;
    uint32_t elapsed_ms;
    uint32_t step;

    if (!s_datetime_valid)
    {
        return;
    }

    now_ms = lv_tick_get();
    elapsed_ms = now_ms - s_datetime_anchor_ms;
    if (elapsed_ms < 1000U)
    {
        return;
    }

    step = elapsed_ms / 1000U;
    while (step--)
    {
        custom_datetime_tick_one_second();
    }
    s_datetime_anchor_ms += (elapsed_ms / 1000U) * 1000U;
}

static void custom_update_screen_datetime_label(uint8_t force)
{
    screen_t *scr;

    if (!s_datetime_valid)
    {
        return;
    }
    if (!force && !s_datetime_dirty && s_last_datetime_ui_sec == s_datetime.second)
    {
        return;
    }

    scr = screen_get(&ui_manager);
    if (!scr->obj || !scr->label_1)
    {
        return;
    }

    lv_label_set_text_fmt(scr->label_1, "%04u-%02u-%02u %02u : %02u : %02u",
                          (unsigned)s_datetime.year,
                          (unsigned)s_datetime.month,
                          (unsigned)s_datetime.day,
                          (unsigned)s_datetime.hour,
                          (unsigned)s_datetime.minute,
                          (unsigned)s_datetime.second);
    s_last_datetime_ui_sec = s_datetime.second;
    s_datetime_dirty = 0U;
}

static void custom_feed_time_frame_byte(uint8_t byte)
{
    if (s_time_frame_idx == 0U)
    {
        if (byte == 0xDAU)
        {
            s_time_frame[0] = byte;
            s_time_frame_idx = 1U;
        }
        return;
    }

    if (s_time_frame_idx == 1U)
    {
        if (byte == 0xEEU)
        {
            s_time_frame[1] = byte;
            s_time_frame_idx = 2U;
            return;
        }
        s_time_frame_idx = (byte == 0xDAU) ? 1U : 0U;
        s_time_frame[0] = byte;
        return;
    }

    if (s_time_frame_idx == 2U)
    {
        if (byte == 0x01U)
        {
            s_time_frame[2] = byte;
            s_time_frame_idx = 3U;
            return;
        }
        s_time_frame_idx = (byte == 0xDAU) ? 1U : 0U;
        s_time_frame[0] = byte;
        return;
    }

    s_time_frame[s_time_frame_idx++] = byte;
    if (s_time_frame_idx >= CUSTOM_TIME_FRAME_LEN)
    {
        uint16_t year = ((uint16_t)s_time_frame[3] << 8) | (uint16_t)s_time_frame[4];
        custom_datetime_set(year, s_time_frame[5], s_time_frame[6],
                            s_time_frame[7], s_time_frame[8], s_time_frame[9]);
        s_time_frame_idx = 0U;
    }
}

