static uint8_t custom_round_play_flash_apng(const char *src)
{
    screen_t *splash;

    if (!src)
    {
        return 0U;
    }

    splash = screen_get(&ui_manager);
    if (!splash || !splash->obj)
    {
        screen_create(&ui_manager);
        splash = screen_get(&ui_manager);
    }
    if (!splash || !splash->obj)
    {
        CUSTOM_UI_ALWAYS("round apng: splash not ready");
        return 0U;
    }

    if (lv_scr_act() != splash->obj)
    {
        lv_scr_load(splash->obj);
    }
    if (splash->image_8)
    {
        lv_obj_add_flag(splash->image_8, LV_OBJ_FLAG_HIDDEN);
    }
    if (s_round_gif_obj)
    {
        lv_gif_pause(s_round_gif_obj);
        lv_obj_add_flag(s_round_gif_obj, LV_OBJ_FLAG_HIDDEN);
    }
#if LV_USE_GIF
    custom_round_qspi_gif_stop();
#endif

    if (!s_round_apng_obj || lv_obj_get_parent(s_round_apng_obj) != splash->obj)
    {
        if (s_round_apng_obj)
        {
            lv_obj_del(s_round_apng_obj);
        }
        s_round_apng_obj = lv_aic_player_create(splash->obj);
        lv_aic_player_set_auto_restart(s_round_apng_obj, true);
    }
    lv_obj_set_pos(s_round_apng_obj, 0, 0);
    lv_obj_set_size(s_round_apng_obj, CUSTOM_DISP_IMG_W, CUSTOM_DISP_IMG_H);
    lv_obj_clear_flag(s_round_apng_obj, LV_OBJ_FLAG_HIDDEN);
    if (lv_aic_player_set_src(s_round_apng_obj, src) != LV_RES_OK)
    {
        CUSTOM_UI_ALWAYS("round apng set src fail %s", src);
        lv_obj_add_flag(s_round_apng_obj, LV_OBJ_FLAG_HIDDEN);
        return 0U;
    }
    lv_aic_player_set_cmd(s_round_apng_obj, LV_AIC_PLAYER_CMD_START, NULL);
    lv_obj_move_foreground(s_round_apng_obj);
    lv_obj_invalidate(s_round_apng_obj);
    CUSTOM_UI_ALWAYS("round apng play %s", src);
    return 1U;
}
